package com.arcus.alert;
import android.app.*;import android.content.*;import android.os.*;import android.media.*;import org.json.*;import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
public class PriceMonitorService extends Service{
static final String ALERT_CHANNEL="arcus_alert_notifications_v2",SERVICE_CHANNEL="arcus_monitor_status",PREF="arcus_native";ScheduledExecutorService executor;final Set<String> activeHits= new HashSet<>();ToneGenerator tone;
public void onCreate(){super.onCreate();createChannels();tone=new ToneGenerator(AudioManager.STREAM_NOTIFICATION,100);startForeground(41,buildService("Watching Arcus prices · 1-second refresh"));executor=Executors.newSingleThreadScheduledExecutor();executor.scheduleWithFixedDelay(this::checkPrices,0,1,TimeUnit.SECONDS);}
public int onStartCommand(Intent i,int f,int id){return START_STICKY;}public IBinder onBind(Intent i){return null;}
void createChannels(){NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26){NotificationChannel s=new NotificationChannel(SERVICE_CHANNEL,"Arcus monitoring status",NotificationManager.IMPORTANCE_LOW);s.setSound(null,null);nm.createNotificationChannel(s);NotificationChannel a=new NotificationChannel(ALERT_CHANNEL,"Arcus price alerts",NotificationManager.IMPORTANCE_HIGH);a.setDescription("Important price level alerts");a.enableVibration(true);a.setLockscreenVisibility(Notification.VISIBILITY_PUBLIC);nm.createNotificationChannel(a);}}
Notification buildService(String s){Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,SERVICE_CHANNEL):new Notification.Builder(this);return b.setContentTitle("Arcus Alert").setContentText(s).setOngoing(true).setSmallIcon(android.R.drawable.ic_dialog_info).build();}
JSONArray levels(){try{return new JSONArray(getSharedPreferences(PREF,0).getString("levels","[]"));}catch(Exception e){return new JSONArray();}}
void checkPrices(){HttpURLConnection c=null;try{c=(HttpURLConnection)new URL("https://api.arcus.xyz/v1/prices").openConnection();c.setConnectTimeout(5000);c.setReadTimeout(5000);c.setUseCaches(false);c.setRequestProperty("Accept","application/json");InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[16384];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);JSONObject d=new JSONObject(out.toString("UTF-8"));getSharedPreferences(PREF,0).edit().putString("markets_json",d.toString()).putLong("markets_updated",System.currentTimeMillis()).remove("monitor_error").apply();JSONArray a=levels();for(int i=0;i<a.length();i++){JSONObject l=a.getJSONObject(i);String sym=l.getString("symbol").toUpperCase(Locale.ROOT);double target=l.getDouble("price");int mode=l.optInt("mode",0);JSONObject item=find(d,sym);if(item==null)continue;Object raw=item.has("markPrice")&&!item.isNull("markPrice")?item.opt("markPrice"):item.opt("oraclePrice");if(raw==null)continue;double price=Double.parseDouble(raw.toString());String key=sym+"|"+target+"|"+mode+"|"+l.optLong("created");String pk="prev:"+key;String old=getSharedPreferences(PREF,0).getString(pk,"");boolean hit=false;if(mode==0||mode==1){if(!old.isEmpty()){double prev=Double.parseDouble(old);boolean crossed=(prev<target&&price>=target)||(prev>target&&price<=target);hit=crossed||Double.compare(price,target)==0;}else{hit=Double.compare(price,target)==0;} }else{hit=Math.abs(price-target)/target*100<=0.1;}getSharedPreferences(PREF,0).edit().putString(pk,Double.toString(price)).apply();String diag="Last check: "+sym+" price="+price+" target="+target+" diff="+(Math.abs(price-target)/target*100)+"% hit="+hit+" at "+new Date();getSharedPreferences(PREF,0).edit().putString("diag:"+key,diag).putString("last_check",diag).apply();if(hit&&activeHits.add(key))alert(sym,target,price);if(!hit)activeHits.remove(key);}((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(41,buildService("Monitoring · "+a.length()+" alerts · 1-second checks"));}catch(Exception e){getSharedPreferences(PREF,0).edit().putString("monitor_error",e.getClass().getSimpleName()+": "+e.getMessage()).apply();}finally{if(c!=null)c.disconnect();}}
JSONObject find(JSONObject d,String symbol){Iterator<String> it=d.keys();while(it.hasNext()){String key=it.next();JSONObject o=d.optJSONObject(key);if(o!=null&&(symbol.equalsIgnoreCase(key)||symbol.equalsIgnoreCase(o.optString("marketDisplayName"))||symbol.equalsIgnoreCase(o.optString("symbol"))||symbol.equalsIgnoreCase(o.optString("marketId"))))return o;}return null;}
void alert(String sym,double target,double price){String body=sym+" touched/crossed "+target+". Current price: "+price;Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,ALERT_CHANNEL):new Notification.Builder(this);b.setContentTitle("Arcus price alert").setContentText(body).setStyle(new Notification.BigTextStyle().bigText(body)).setSmallIcon(android.R.drawable.ic_dialog_alert).setAutoCancel(true).setPriority(Notification.PRIORITY_MAX).setDefaults(Notification.DEFAULT_ALL);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify((int)(System.currentTimeMillis()%Integer.MAX_VALUE),b.build());try{tone.startTone(ToneGenerator.TONE_PROP_BEEP,1000);}catch(Exception ignored){}getSharedPreferences(PREF,0).edit().putString("last_alert",body+" @ "+new Date()).apply();}
public void onDestroy(){if(executor!=null)executor.shutdownNow();if(tone!=null)tone.release();super.onDestroy();}
}